def original_source(feature):
    """The original generator a placed feature ports (family level)."""
    if feature.startswith('ore_nether_'):
        return 'original HbmWorldGen.java:509-518'
    if feature.startswith('depth_ore_nether'):
        return 'original HbmWorldGen.java:529-530'
    if feature.startswith('depth_'):
        return 'original HbmWorldGen.java:105-110'
    if feature.startswith('ore_gneiss_'):
        return 'original HbmWorldGen.java:112-119'
    if feature.startswith('cluster_'):
        return 'original HbmWorldGen.java:138-141'
    if feature == 'resource_limestone':
        return 'original HbmWorldGen.java:143'
    if feature.endswith('_layer_placed'):
        return 'original MainRegistry.java:602-604 (OreLayer3D)'
    if feature == 'schist_stratum_placed':
        return 'original MainRegistry.java:597 (SchistStratum)'
    if feature == 'smoldering_netherrack_placed':
        return 'original HbmWorldGen.java:533-541'
    if feature == 'coltan_deposit_placed':
        return 'original HbmWorldGen.java:159-179'
    if feature == 'ore_tikite_placed':
        return 'original HbmWorldGen.java generateEnd'
    if feature in RARE:
        return RARE[feature][1]
    if feature.startswith('ore_'):
        return 'original HbmWorldGen.java:121-136 (NEO adds the deepslate variants)'
    return ''


def placed_path(feature):
    for root in (GENERATED, HANDWRITTEN):
        p = root / 'placed_feature' / (feature + '.json')
        if p.is_file():
            return p
    return None


def describe(feature, gates):
    """Per-chunk attempts, height and vein size of a placed feature from its JSON (and the gate defaults of the row)."""
    p = placed_path(feature)
    if p is None:
        return 'placed by code'
    d = json.loads(p.read_text(encoding='utf-8'))
    defaults = dict(gates)
    parts = []
    for m in d.get('placement', []):
        t = m.get('type', '').split(':')[-1]
        if t == 'count':
            parts.append('%s veins/chunk' % m['count'])
        elif t == 'config_count':
            parts.append('%s veins/chunk (%s)' % (defaults.get(m['config'], '?'), m['config']))
        elif t == 'rarity_filter':
            parts.append('1/%d chunks' % m['chance'])
        elif t == 'config_rarity':
            parts.append('1/%s chunks (%s)' % (defaults.get(m['config'], '?'), m['config']))
        elif t == 'height_range':
            h = m['height']
            lo, hi = h.get('min_inclusive', {}), h.get('max_inclusive', {})
            parts.append('y %s..%s' % (lo.get('absolute', 'bottom+%s' % lo.get('above_bottom')), hi.get('absolute', 'bottom+%s' % hi.get('above_bottom'))))
    cf = d.get('feature', '')
    cfname = cf.split(':')[-1] if isinstance(cf, str) else ''
    for root in (GENERATED, HANDWRITTEN):
        q = root / 'configured_feature' / (cfname + '.json')
        if q.is_file():
            c = json.loads(q.read_text(encoding='utf-8')).get('config', {})
            if 'size' in c:
                parts.append('size %s' % c['size'])
            break
    if not d.get('placement'):
        parts.insert(0, 'once per chunk, the feature decides')
    return ', '.join(parts) or 'no placement modifiers'


def blocks():
    """Unique listed blocks: name -> dict(dims, features, codes, on, gates)."""
    out = collections.OrderedDict()
    for block, biome, feature, code, gates, on in WORLDGEN:
        e = out.setdefault(block, dict(dims=set(), features=[], codes=[], on=True, gates=[]))
        e['dims'].add({'is_nether': 'nether', 'is_end': 'end'}.get(biome, 'overworld'))
        if feature not in e['features']:
            e['features'].append(feature)
        if code and code not in e['codes']:
            e['codes'].append(code)
        e['on'] = e['on'] and on
        e['gates'] += [g for g in gates if g not in e['gates']]
    return out


def rule_of(name, e):
    if name in LIST_PROBLEMS:
        return 'list'
    if not e['on']:
        return 'absent'
    if e['dims'] == {'end'}:
        return 'end'
    if all(f in REGION_FEATURES or f.startswith('ore_gneiss_') for f in e['features']):
        return 'region'
    if all(f in RARE for f in e['features']):
        return 'rare'
    return 'common'


def eid_of(name):
    return '%s.block-%s' % (OWNER.get(name, 'world-generation'), name)


