class JavaRandom:
    """java.util.Random (seed scrambling, next, nextDouble, nextGaussian), for the coltan deposit centre."""

    def __init__(self, seed):
        self.seed = (seed ^ 0x5DEECE66D) & ((1 << 48) - 1)
        self.next_gaussian = None

    def next(self, bits):
        self.seed = (self.seed * 0x5DEECE66D + 0xB) & ((1 << 48) - 1)
        v = self.seed >> (48 - bits)
        return v - (1 << 32) if v >= (1 << 31) else v

    def next_double(self):
        return ((self.next(26) << 27) + self.next(27)) * (1.0 / (1 << 53))

    def gaussian(self):
        if self.next_gaussian is not None:
            g, self.next_gaussian = self.next_gaussian, None
            return g
        while True:
            v1 = 2 * self.next_double() - 1
            v2 = 2 * self.next_double() - 1
            s = v1 * v1 + v2 * v2
            if 0 < s < 1:
                break
        m = math.sqrt(-2 * math.log(s) / s)
        self.next_gaussian = v2 * m
        return v1 * m


def coltan_centre(seed):
    """ColtanDepositFeature.depositCentre (ColtanDepositFeature.java:47-52; original HbmWorldGen.java:159-161)."""
    r = JavaRandom(seed + 5)
    return int(r.gaussian() * 1500), int(r.gaussian() * 1500)


def is_blueprint_chunk(cx, cz):
    i, j = cx * 16, cz * 16
    return not (abs(i) < 100 and abs(j) < 100) and abs(i) % BLUEPRINT_GRID < 16 and abs(j) % BLUEPRINT_GRID < 16


def wait_loaded(ctx, x, z, radius, dim=None, timeout_s=240):
    """Polls the server until the chunks at the corners of the walk point's view area (and the centre) are loaded."""
    prefix = 'execute in %s ' % dim if dim else 'execute '
    points = [(x, z)] + [(x + dx * radius * 16, z + dz * radius * 16) for dx in (-1, 1) for dz in (-1, 1)] if radius else [(x, z)]
    started = time.time()
    pending = list(points)
    while pending and time.time() - started < timeout_s:
        pending = [p for p in pending if not ctx.server('%sif loaded %d 64 %d' % (prefix, p[0], p[1]), allow_error=True)['result']]
        if pending:
            time.sleep(1.0)
    ctx.step('wait', ticks=20)
    return round(time.time() - started, 1), not pending


def walk(ctx, points, y, radius, dim=None, log=None):
    for x, z in points:
        ctx.step('view', pos=[x + 0.5, y, z + 0.5], pitch=0.0, yaw=0.0, fly=True, hide_gui=False)
        secs, ok = wait_loaded(ctx, x, z, radius, dim)
        if log is not None:
            log.append(dict(dim=dim or 'minecraft:overworld', x=x, z=z, s=secs, loaded=ok))


# ---------------------------------------------------------------- region reading

def run_scan(region, out_json):
    """scan_region.py over a closed world's region directory: hbmsntm blocks, per-chunk lists and blueprint chests."""
    started = time.time()
    p = subprocess.run([sys.executable, '-B', '-X', 'utf8', str(SCAN_SCRIPT), str(region), '--chunks', '--blueprint-chests',
                        '--json', str(out_json)], capture_output=True, text=True, timeout=1800)
    if p.returncode != 0:
        raise RuntimeError('scan_region.py %s failed (%d): %s' % (region, p.returncode, (p.stderr or p.stdout)[-400:]))
    data = json.loads(Path(out_json).read_text(encoding='utf-8'))
    data['wall_s'] = round(time.time() - started, 1)
    return data


class Region:
    """Random access to the blocks of a closed world's region directory (status full chunks only)."""

    def __init__(self, directory):
        self.dir = Path(directory)
        self.files = {}
        self.chunks = {}

    def chunk(self, cx, cz):
        key = (cx, cz)
        if key not in self.chunks:
            self.chunks[key] = self._load(cx, cz)
        return self.chunks[key]

    def _load(self, cx, cz):
        import gzip
        import struct
        import zlib
        name = 'r.%d.%d.mca' % (cx >> 5, cz >> 5)
        if name not in self.files:
            path = self.dir / name
            self.files[name] = path.read_bytes() if path.is_file() else b''
        data = self.files[name]
        if len(data) < 8192:
            return None
        off = struct.unpack_from('>I', data, ((cx & 31) + (cz & 31) * 32) * 4)[0]
        if off >> 8 == 0:
            return None
        p = (off >> 8) * 4096
        ln = struct.unpack_from('>I', data, p)[0]
        raw = data[p + 5:p + 4 + ln]
        raw = zlib.decompress(raw) if data[p + 4] == 2 else gzip.decompress(raw) if data[p + 4] == 1 else None
        if raw is None:
            return None
        nbt = scan_region.read_compound_with_longs(raw)
        if nbt.get('Status') not in ('minecraft:full', 'full'):
            return None
        return dict(raw={s['Y']: s for s in nbt['sections'] if s.get('block_states')}, dec={})

    def section(self, cx, cz, sy):
        ch = self.chunk(cx, cz)
        if ch is None:
            return None, None
        if sy not in ch['dec']:
            ch['dec'][sy] = scan_region.decode(ch['raw'][sy]) if sy in ch['raw'] else (None, None)
        return ch['dec'][sy]

    def at(self, x, y, z):
        pal, idx = self.section(x >> 4, z >> 4, y >> 4)
        if pal is None:
            return None
        return pal[0] if idx is None else pal[idx[((y & 15) << 8) | ((z & 15) << 4) | (x & 15)]]

    def find(self, cx, cz, want):
        """Positions in a chunk whose block name satisfies want(name)."""
        ch = self.chunk(cx, cz)
        if ch is None:
            return []
        out = []
        for sy, s in sorted(ch['raw'].items()):
            if not any(want(e['Name']) for e in s['block_states']['palette']):
                continue
            pal, idx = self.section(cx, cz, sy)
            for j in range(4096):
                if want(pal[idx[j] if idx is not None else 0]):
                    out.append((cx * 16 + (j & 15), sy * 16 + (j >> 8), cz * 16 + ((j >> 4) & 15)))
        return out


def deposits(chunk_rows):
    """Connected groups (8-neighbour) of chunks holding a block: one bedrock-oil deposit spans at most 9 x 9 blocks."""
    left = {(c[0], c[1]) for c in chunk_rows}
    groups = 0
    while left:
        stack = [left.pop()]
        groups += 1
        while stack:
            cx, cz = stack.pop()
            for dx in (-1, 0, 1):
                for dz in (-1, 0, 1):
                    n = (cx + dx, cz + dz)
                    if n in left:
                        left.remove(n)
                        stack.append(n)
    return groups


def poisson_range(lam, alpha=0.001):
    """Smallest and largest counts whose tails each hold at least alpha / 2 of the Poisson(lam) mass."""
    pmf, k, acc, lo = math.exp(-lam), 0, 0.0, 0
    while True:
        acc += pmf
        if acc > alpha / 2:
            lo = k
            break
        k += 1
        pmf *= lam / k
    pmf, k, acc = math.exp(-lam), 0, 0.0
    while True:
        acc += pmf
        if acc >= 1 - alpha / 2:
            return lo, k
        k += 1
        pmf *= lam / k


# ---------------------------------------------------------------- survival opening helpers

AIR = ('minecraft:air', 'minecraft:cave_air')
GROUND = ('minecraft:grass_block', 'minecraft:dirt', 'minecraft:podzol', 'minecraft:coarse_dirt', 'minecraft:rooted_dirt',
          'minecraft:mycelium', 'minecraft:moss_block', 'minecraft:stone', 'minecraft:sand', 'minecraft:mud')
STONES = ('minecraft:stone', 'minecraft:deepslate')            # drop cobblestone / cobbled deepslate to a pickaxe
ROCK = STONES + ('minecraft:granite', 'minecraft:diorite', 'minecraft:andesite', 'minecraft:tuff', 'minecraft:calcite')
COBBLE = ('minecraft:cobblestone', 'minecraft:cobbled_deepslate')
# Ores the opening may mine: the original ones that drop themselves and smelt to an ingot.
# block -> (ingot, original smelting line, NEO smelting line, NEO loot line)
SMELTABLE = {
    'ore_titanium': ('ingot_titanium', 'SmeltingRecipes.java:36', 'NtmRecipeProvider.java:2681', 'NtmBlockLootTableProvider.java:68'),
    'ore_tungsten': ('ingot_tungsten', 'SmeltingRecipes.java:38', 'NtmRecipeProvider.java:2680', 'NtmBlockLootTableProvider.java:66'),
    'ore_lead': ('ingot_lead', 'SmeltingRecipes.java:41', 'NtmRecipeProvider.java:2682', 'NtmBlockLootTableProvider.java:70'),
    'ore_beryllium': ('ingot_beryllium', 'SmeltingRecipes.java:42', 'NtmRecipeProvider.java:2650', 'NtmBlockLootTableProvider.java:64'),
    'ore_thorium': ('ingot_th232', 'SmeltingRecipes.java:30', 'NtmRecipeProvider.java:2687', 'NtmBlockLootTableProvider.java:77'),
}
COOK = 200           # NtmRecipeProvider.java:3085 (every ore smelting recipe); the 1.7.10 furnace also cooks 200 ticks
# Held attacks end a little after the block breaks: a held key goes on to mine the next block in the crosshair after the
# 5-tick destroy delay, so a hold must end before that block could break as well. A hold that ended too early is repeated
# from scratch (progress is lost on release); the last value of a tuple is the one repeated.
LOG_HOLD = (64,)     # a log by hand: 1 / 2.0 / 30 a tick = 60 ticks
TABLE_HOLD = (78,)   # a crafting table by hand: 1 / 2.5 / 30 a tick = 75 ticks
ORE_HOLD = (85,)     # wooden pickaxe on the ore: the original's hardness 5.0 needs 75 ticks (ModBlocks.java:1241)
STONE_HOLD = {'minecraft:stone': (26,), 'minecraft:deepslate': (48,)}   # wooden pickaxe: 2 / 1.5 / 30 -> 23 ticks, 2 / 3 / 30 -> 45 ticks
FACE = {(0, 0, 1): 'south', (0, 0, -1): 'north', (1, 0, 0): 'east', (-1, 0, 0): 'west'}

INV_MENU = lambda i: 36 + i if i < 9 else i          # noqa: E731  InventoryMenu: 0 result, 1-4 grid, 9-35, 36-44 hotbar
CRAFT_MENU = lambda i: 37 + i if i < 9 else i + 1    # noqa: E731  CraftingMenu: 0 result, 1-9 grid, 10-36, 37-45 hotbar
FURNACE_MENU = lambda i: 30 + i if i < 9 else i - 6  # noqa: E731  FurnaceMenu: 0 input, 1 fuel, 2 result, 3-29, 30-38 hotbar


def add(p, v, k=1):
    return (p[0] + v[0] * k, p[1] + v[1] * k, p[2] + v[2] * k)


def find_tree(region, spawn, radius=6):
    """A tree near the spawn with three logs of one kind standing on the ground, a free standing cell beside its foot (P,
    air up to the fourth block) on ground, and a free cell beyond P (Q, for the crafting table). Nearest first."""
    scx, scz = int(spawn[0]) >> 4, int(spawn[2]) >> 4
    found = []
    for cx in range(scx - radius, scx + radius + 1):
        for cz in range(scz - radius, scz + radius + 1):
            for x, y, z in region.find(cx, cz, lambda n: n.endswith('_log') and 'stripped' not in n):
                log = region.at(x, y, z)
                if region.at(x, y - 1, z) not in GROUND or any(region.at(x, y + k, z) != log for k in (1, 2)):
                    continue
                for v in FACE:
                    p = add((x, y, z), v)
                    q = add(p, v)
                    if (all(region.at(p[0], p[1] + k, p[2]) in AIR for k in range(4)) and region.at(p[0], p[1] - 1, p[2]) in GROUND
                            and region.at(*q) in AIR and region.at(q[0], q[1] + 1, q[2]) in AIR and region.at(q[0], q[1] - 1, q[2]) in GROUND):
                        found.append(((x - spawn[0]) ** 2 + (z - spawn[2]) ** 2, (x, y, z), v, log))
    found.sort()
    return found[0][1:] if found else None


def find_ore(region, spawn, radius=6):
    """A smeltable HBM ore O in solid rock, with the pocket below its south side: the player's head cell H = O + south,
    feet F = H - 1, eight stone or deepslate blocks around the pocket to mine (N1 under O, both sides at feet and head,
    behind at feet and head, the ceiling), and solid rock everywhere in the 5 x 5 x 5 cube around H. Nearest first."""
    scx, scz = int(spawn[0]) >> 4, int(spawn[2]) >> 4
    names = {H + b for b in SMELTABLE}
    best = None
    for cx in range(scx - radius, scx + radius + 1):
        for cz in range(scz - radius, scz + radius + 1):
            for o in region.find(cx, cz, lambda n: n in names):
                if not 8 <= o[1] <= 50:
                    continue
                hd = add(o, (0, 0, 1))
                ft = add(hd, (0, -1, 0))
                targets = pocket_targets(o, ft, hd)
                if any(region.at(*t[0]) not in STONES for t in targets):
                    continue
                cube_ok = True
                for dx in range(-2, 3):
                    for dy in range(-2, 3):
                        for dz in range(-2, 3):
                            c = (hd[0] + dx, hd[1] + dy, hd[2] + dz)
                            n = region.at(*c)
                            if c == o or n in ROCK or (n or '').endswith('_ore') or (n or '').startswith(H + 'ore_'):
                                continue
                            cube_ok = False
                if not cube_ok:
                    continue
                d = (o[0] - spawn[0]) ** 2 + (o[2] - spawn[2]) ** 2
                if best is None or d < best[0]:
                    best = (d, o, ft, hd, region.at(*o))
    return best[1:] if best else None


def pocket_targets(o, ft, hd):
    """(block, face hit from the pocket) for the eight stones: under O, east/west/south at feet and head, the ceiling."""
    return [(add(o, (0, -1, 0)), 'south'), (add(ft, (1, 0, 0)), 'west'), (add(hd, (1, 0, 0)), 'west'), (add(ft, (-1, 0, 0)), 'east'),
            (add(hd, (-1, 0, 0)), 'east'), (add(ft, (0, 0, 1)), 'north'), (add(hd, (0, 0, 1)), 'north'), (add(hd, (0, 1, 0)), 'down')]


def stack_key(entry):
    meta = (entry.get('components') or {}).get('hbmsntm:meta')
    return entry['id'] + ('@%d' % meta if meta else '')


def inventory(ctx):
    """Server-side player inventory as Counter(item id[@meta] -> count)."""
    r = ctx.server('data get entity @p Inventory')
    lines = [m for m in r['messages'] if m.strip()]
    value = _lib.data_value(lines[-1]) if lines else []
    out = Counter()
    for entry in value if isinstance(value, list) else []:
        out[stack_key(entry)] += entry.get('count', 1)
    return out


def inventory_raw(ctx):
    r = ctx.server('data get entity @p Inventory')
    lines = [m for m in r['messages'] if m.strip()]
    value = _lib.data_value(lines[-1]) if lines else []
    return sorted(([e.get('Slot'), e.get('id'), e.get('count', 1), json.dumps(e.get('components', {}), sort_keys=True)]
                   for e in (value if isinstance(value, list) else [])), key=lambda t: t[0])


def delta(after, before):
    return {k: after[k] - before.get(k, 0) for k in set(after) | set(before) if after[k] - before.get(k, 0)}


def is_block(ctx, pos, block):
    return bool(ctx.server('execute if block %d %d %d %s' % (pos[0], pos[1], pos[2], block), allow_error=True)['result'])


def client_slot(ctx, item):
    """Lowest player-inventory index holding item (client copy, used only to find where to click)."""
    inv = ctx.step('inv')
    if inv['carried'].get('count'):
        raise RuntimeError('an item is still carried: %s' % inv['carried'])
    for s in sorted(inv['slots'], key=lambda s: s['slot']):
        if s['item'] == item and s['slot'] < 36:
            return s['slot'], s['count']
    raise RuntimeError('%s is not in the inventory: %s' % (item, [(s['slot'], s['item'], s['count']) for s in inv['slots']]))


def put(ctx, menu, item, targets, each=1):
    """Picks up the stack of `item`, right-clicks `each` items into every target slot, puts the rest back."""
    i, count = client_slot(ctx, item)
    if count < each * len(targets):
        raise RuntimeError('%s: %d in slot %d, %d needed' % (item, count, i, each * len(targets)))
    ctx.step('click', slot=menu(i))
    for t in targets:
        for _ in range(each):
            ctx.step('click', slot=t, button=1, after=1)
    if count > each * len(targets):
        ctx.step('click', slot=menu(i))


def put_all(ctx, menu, item, target):
    i, _ = client_slot(ctx, item)
    ctx.step('click', slot=menu(i))
    ctx.step('click', slot=target)


def shift_click(ctx, slot):
    ctx.step('mod', shift=True)
    try:
        ctx.step('click', slot=slot)
    finally:
        ctx.step('mod', shift=False)


def hold(ctx, item, hotbar=8):
    """Puts `item` into hotbar slot `hotbar` (number-key swap over the slot in the inventory screen) and selects it."""
    i, _ = client_slot(ctx, item)
    if i != hotbar:
        ctx.step('key', key='key.keyboard.e', after=4)
        ctx.step('screen', expect='InventoryScreen')
        ctx.step('hover', slot=INV_MENU(i))
        ctx.step('wait', ticks=2)
        ctx.step('key', key='key.keyboard.%d' % (hotbar + 1), after=3)
        ctx.step('close')
    ctx.step('key', key='key.keyboard.%d' % (hotbar + 1), after=3)
    inv = ctx.step('inv')
    held = [s for s in inv['slots'] if s['slot'] == inv['selected']]
    if not held or held[0]['item'] != item:
        raise RuntimeError('holding %s, wanted %s' % (held, item))


def focused(ctx, max_waits=900):
    """A held attack mines only while the client window has the focus and the mouse is grabbed; a second client on the same
    desktop takes the focus, so this waits (1 s steps) until the window is active, then opens and closes the inventory."""
    ctx.step('close', allow_fail=True)
    for _ in range(max_waits):
        if ctx.step('wait', ticks=20).get('window_active'):
            break
    else:
        raise RuntimeError('the client window had no focus for %d s: held attacks cannot mine' % max_waits)
    ctx.step('key', key='key.keyboard.e', after=4)
    ctx.step('close')


def stand(ctx, feet, look):
    ctx.step('view', pos=[feet[0] + 0.5, feet[1], feet[2] + 0.5], look_at=[look[0] + 0.5, look[1] + 0.5, look[2] + 0.5], fly=False, hide_gui=False)


def mine(ctx, pos, face, hold_ticks, feet):
    """Attacks `face` of the block at pos from the standing cell `feet` (repeated when a hold ends before the block broke),
    waits for the pickup; returns (inventory delta, block gone)."""
    before = inventory(ctx)
    holds = tuple(hold_ticks) if isinstance(hold_ticks, (tuple, list)) else (hold_ticks,)
    for attempt in range(4):
        if attempt:
            focused(ctx)
        stand(ctx, feet, pos)
        ctx.step('attack', target=dict(pos=list(pos), face=face), hold=holds[min(attempt, len(holds) - 1)], after=2)
        if is_block(ctx, pos, 'minecraft:air'):
            break
    gone = is_block(ctx, pos, 'minecraft:air')
    ctx.step('wait', ticks=25)
    if gone and not delta(inventory(ctx), before):
        collect(ctx, pos, feet)
    return delta(inventory(ctx), before), gone


def collect(ctx, pos, feet):
    """A drop that rolled out of reach is walked to, as a player would: stands on the nearest item entity's cell when it lies
    at the standing height and that cell is free, waits for the pickup and steps back."""
    r = ctx.server('execute positioned %d %d %d run data get entity @e[type=minecraft:item,distance=..5,sort=nearest,limit=1] Pos'
                   % tuple(pos), allow_error=True)
    lines = [m for m in r['messages'] if m.strip()]
    try:
        p = _lib.data_value(lines[-1]) if lines else None
    except ValueError:
        p = None
    if not isinstance(p, list) or len(p) != 3 or abs(p[1] - feet[1]) > 1.5:
        return
    cell = (int(math.floor(p[0])), feet[1], int(math.floor(p[2])))
    if not (is_block(ctx, cell, 'minecraft:air') and is_block(ctx, (cell[0], cell[1] + 1, cell[2]), 'minecraft:air')):
        return
    ctx.step('view', pos=[cell[0] + 0.5, feet[1], cell[2] + 0.5], pitch=0.0, yaw=0.0, fly=False, hide_gui=False)
    ctx.step('wait', ticks=20)
    stand(ctx, feet, pos)


def open_block(ctx, pos, face, feet, screen_word):
    ctx.step('close')
    stand(ctx, feet, pos)
    ctx.step('use', target=dict(pos=list(pos), face=face), after=6)
    ctx.step('screen', expect=screen_word)


def place(ctx, item, pos, feet):
    """Real placement: item in hand, use on the top face of the block under pos."""
    hold(ctx, item)
    stand(ctx, feet, (pos[0], pos[1] - 1, pos[2]))
    below = (pos[0], pos[1] - 1, pos[2])
    ctx.step('use', target=dict(pos=list(below), face='up'), after=6)
    if not is_block(ctx, pos, item):
        raise RuntimeError('%s was not placed at %s' % (item, pos))


def furnace_items(ctx, pos):
    d = _lib.block_data(ctx, pos)
    return {e.get('Slot'): (stack_key(e), e.get('count', 1)) for e in d.get('Items', [])}


def section(ctx, rows, body, reason_prefix):
    """Runs one independent part; on an error its undecided rows become not-run with the reason."""
    try:
        ctx.step('close', allow_fail=True)
        ctx.step('mod', shift=False, allow_fail=True)
        body()
        return None
    except Exception as e:  # noqa: BLE001 - a broken section must not take the next one with it
        result = getattr(e, 'result', None)
        reason = '%s: %s' % (reason_prefix, 'step %s (%s) failed: %s' % (result.get('seq'), result.get('op'), result.get('reason'))
                                            if isinstance(result, dict) else repr(e)[:300])
        for eid in rows:
            if eid not in ctx.verdicts:
                ctx.not_run(eid, reason)
        try:
            ctx.step('close', allow_fail=True)
        except Exception:  # noqa: BLE001
            pass
        return reason


# ---------------------------------------------------------------- expectations

def expectations():
    W = 'world-generation.'
    E = [
        (W + 'world-settings', 'the run\'s world: survival game mode, difficulty not peaceful (normal), default terrain; the seed is recorded',
         'drive.py world settings; server `difficulty` and `seed`'),
        (W + 'scan-range', 'the walk generated and the scan counted at least %d full overworld chunks ((499/500)^N <= 1 %%: the crashed '
                           'bomb, NtmPlacedFeatures.java:112) and %d full nether chunks; 8 blueprint candidate chunks among them'
         % (N_MIN_OVERWORLD, N_MIN_NETHER),
         'NtmPlacedFeatures.java:112; original WorldConfig.java:87; BlueprintChestFeature.java:36-44'),
    ]
    for name, e in blocks().items():
        rule = rule_of(name, e)
        dims = '/'.join(sorted(e['dims']))
        how = '; '.join('%s: %s' % (f, describe(f, e['gates'])) for f in e['features'])
        if rule == 'absent':
            text = 'ABSENT from every scanned %s chunk: off by default (%s)' % (dims, ', '.join('%s=%s' % g for g in e['gates']))
        elif rule == 'end':
            text = 'End only: outside this smoke (no End scan)'
        elif rule == 'rare':
            text = 'at least one in the scanned %s chunks; none found: left for a person with P(none in N chunks)' % dims
        elif rule == 'region':
            text = 'at least one in the scanned %s chunks; none found: left for a person (noise-placed region outside the scan)' % dims
        elif rule == 'list':
            text = 'at least one in the scanned %s chunks, as the list says (its listed source does not place it)' % dims
        else:
            text = 'at least one in the scanned %s chunks' % dims
        src = '; '.join(filter(None, ['%s (%s)' % (how, ', '.join(e['codes'])) if e['codes'] else how,
                                      '; '.join(dict.fromkeys(original_source(f) for f in e['features']))]))
        E.append((eid_of(name), text, src))
    E += [
        ('blueprints.worldgen-chest', 'at least one blueprint chest (a vanilla chest with obsidian on all 26 neighbours) in the visited '
                                      'candidate chunks; none found: left for a person with P(none) = 0.5^k',
         'BlueprintChestFeature.java:36-44,55-70; original HbmWorldGen.java:480-505'),
        (W + 'bedrock-oil-rate', 'bedrock-oil deposits (groups of neighbouring chunks holding ore_bedrock_oil) in the scanned overworld '
                                 'chunks lie in the 99.9 % Poisson range of N/200, the original rate',
         'original WorldConfig.java:32,149, MapGenBedrockOil.java:37 (rand.nextInt(200) == 198 per chunk), HbmWorld.java:76-79; '
         'NEO NtmPlacedFeatures.java:110, BedrockOilDepositFeature.java:26-46'),
        (W + 'opening-wood', 'survival, empty hand: three logs of one tree near the spawn broken by hand (held attack) give 3 logs',
         'vanilla log drop; real attack steps'),
        (W + 'opening-tools', 'real slot clicks: 3 logs -> 12 planks (inventory grid), 1 crafting table, 4 sticks; the table placed on the '
                              'ground and opened; 3 planks + 2 sticks -> 1 wooden pickaxe; the table broken (held attack, at hand speed: the pickaxe '
                              'in the selected slot is not its tool) and picked up '
                              '(3 planks, 2 sticks, 1 table, 1 pickaxe in the inventory)',
         'vanilla crafting recipes; real clicks'),
        (W + 'opening-ore', 'wooden pickaxe on a generated HBM ore near the spawn: it breaks and drops 1 of itself (the two cells the '
                            'player stands in under the ore are cleared by command first: 预写 standing room, not machine state)',
         '; '.join('%s: NEO %s, original BlockGeneric (drops itself)' % (b, v[3]) for b, v in SMELTABLE.items())),
        (W + 'opening-furnace', 'eight stone/deepslate blocks around the pocket mined with the pickaxe give 8 cobblestone/cobbled deepslate; '
                                'a crafting table placed, a furnace crafted (8 in a ring) and placed',
         'vanilla stone drops and furnace recipe; real placement and clicks'),
        (W + 'opening-smelt', 'the mined ore and 2 planks in the furnace (real clicks): after %d+ ticks 1 ingot in the result slot, 1 plank '
                              'left; taken out: +1 ingot in the player inventory' % COOK,
         '; '.join('%s -> %s: original %s, NEO %s' % (b, v[0], v[1], v[2]) for b, v in SMELTABLE.items()) + '; cook time NtmRecipeProvider.java:3085'),
        (W + 'reopen', 'leave and open the world again: the player inventory (slots, items, counts, components such as the pickaxe damage) '
                       'and the furnace contents read on the server are the same as before',
         'player data and block-entity save'),
        (W + 'reopen-worldgen', 'after the reopen the server finds the scanned rare blocks where the closed world\'s region files had them '
                                '(crashed bomb, landmine, blueprint chest, oil), and a generated landmine still waits for a player (Waiting 1b)',
         'LandmineFeature.java:41-45, LandmineBlockEntity.java:82-93; original HbmWorldGen.java:286-291'),
        ('oil-extraction.sand-oil-bubble-look',
         'the surface of a sand oil bubble found in the scanned chunks (an oil spill with oily sand around it and tar sand just below), seen from above and '
         'from over its shaft: a patch of oily sand about 14 blocks across (darker than the sand around it) with a shaft two blocks deep at its centre whose '
         'floor is the oil spill',
         'original MapGenBubble.java:93-134 (the oily surface spots), :148-174 (the hole: two solids removed, the third the oil spill); '
         'NEO SandOilBubbleFeature.java addSurfaceSpot'),
    ]
    return [dict(id=i, text=t, source=s) for i, t, s in E]


# ---------------------------------------------------------------- the run

def run(ctx):
    ids = [e['id'] for e in expectations()]
    W = 'world-generation.'
    state = dict(walk=[], scans={})
    world = getattr(ctx.run, 'world', None) or {}
    client = ctx.default
    saves = common.CLIENTS / client / 'saves' / world.get('name', '')

    # world settings (read on the server)
    def settings():
        inv = ctx.step('inv')
        diff = ctx.server('difficulty')
        seed_text = ' '.join(ctx.server('seed')['messages'])
        import re
        m = re.search(r'\[(-?\d+)\]', seed_text)
        state['seed'] = int(m.group(1)) if m else None
        pos = _lib.data_value(ctx.server('data get entity @p Pos')['messages'][-1])
        state['spawn'] = [float(c) for c in pos]
        ctx.check(W + 'world-settings', str(inv.get('game_mode', '')).lower() == 'survival' and diff['result'] in (1, 2, 3)
                  and world.get('preset') == 'normal' and state['seed'] is not None,
                  'game mode %s, difficulty id %s, preset %s, seed %s, spawn %s'
                  % (inv.get('game_mode'), diff['result'], world.get('preset'), state['seed'], [round(c, 1) for c in state['spawn']]))
    section(ctx, [W + 'world-settings'], settings, 'world settings')
    spawn = state.get('spawn') or [0.0, 80.0, 0.0]
    seed = state.get('seed') if state.get('seed') is not None else int(world.get('seed', 31))

    # the walk: spectator, view areas one after the other
    def walk_all():
        ctx.server('gamemode spectator @a')
        old = ctx.step('option', name='renderDistance', value=RD_SCAN)
        state['render_old'] = int(old.get('old', RD_SCAN))
        sx, sz = int(spawn[0]), int(spawn[2])
        points = [(sx + dx, sz + dz) for dz in GRID for dx in GRID]
        walk(ctx, points, 200, LOADED_RADIUS, log=state['walk'])
        cx, cz = coltan_centre(seed)
        state['coltan_centre'] = (cx, cz)
        if not any(abs(cx - x) < 100 and abs(cz - z) < 100 for x, z in points):
            walk(ctx, [(cx, cz)], 200, LOADED_RADIUS, log=state['walk'])
        r = ctx.server('locate biome #minecraft:is_badlands', allow_error=True)
        import re
        m = re.search(r'\[(-?\d+),\s*[~\-\d]+,\s*(-?\d+)\]', ' '.join(r['messages']))
        if m and abs(int(m.group(1)) - sx) + abs(int(m.group(2)) - sz) < 6000:
            state['badlands'] = (int(m.group(1)), int(m.group(2)))
            walk(ctx, [state['badlands']], 200, LOADED_RADIUS, log=state['walk'])
        else:
            state['badlands'] = None
        ctx.step('option', name='renderDistance', value=RD_BLUEPRINT)
        walk(ctx, [(x + 8, z + 8) for x, z in BLUEPRINT_CORNERS], 200, 0, log=state['walk'])
        ctx.step('option', name='renderDistance', value=RD_SCAN)
        ctx.server('execute in minecraft:the_nether run tp @a 0.5 64 0.5')
        ctx.step('wait', ticks=40)
        walk(ctx, [(dx, dz) for dz in NETHER_GRID for dx in NETHER_GRID], 64, LOADED_RADIUS, dim='minecraft:the_nether', log=state['walk'])
        ctx.server('execute in minecraft:overworld run tp @a %.1f %.1f %.1f' % tuple(spawn))
        ctx.step('wait', ticks=40)
        ctx.step('option', name='renderDistance', value=state['render_old'])
        ctx.server('gamemode survival @a')
    walk_reason = section(ctx, [], walk_all, 'walk')
    state['walk_reason'] = walk_reason
    if walk_reason:
        try:
            ctx.server('execute in minecraft:overworld run tp @a %.1f %.1f %.1f' % tuple(spawn), allow_error=True)
            ctx.server('gamemode survival @a', allow_error=True)
            if state.get('render_old'):
                ctx.step('option', name='renderDistance', value=state['render_old'], allow_fail=True)
        except Exception:  # noqa: BLE001
            pass

    # leave, count the closed world's region files, open again
    scan_rows = [i for i in ids if '.block-' in i] + ['blueprints.worldgen-chest', W + 'bedrock-oil-rate', W + 'scan-range']

    def scan():
        ctx.step('leave')
        time.sleep(2)
        out = ctx.run.dir / client
        out.mkdir(parents=True, exist_ok=True)
        state['scans']['overworld'] = run_scan(saves / 'region', out / 'scan-overworld.json')
        nether = saves / 'DIM-1' / 'region'
        state['scans']['nether'] = run_scan(nether, out / 'scan-nether.json') if nether.is_dir() else dict(scanned=0, blocks={})
        ctx.step('openworld', world=world.get('name'))
        judge_scan(ctx, state)
    scan_reason = section(ctx, scan_rows, scan, 'scan')
    if scan_reason:
        try:
            ctx.step('openworld', world=world.get('name'), allow_fail=True)
        except Exception:  # noqa: BLE001
            pass

    # survival opening near the spawn (positions from the closed world's region files)
    open_rows = [W + 'opening-wood', W + 'opening-tools', W + 'opening-ore', W + 'opening-furnace', W + 'opening-smelt']

    def opening():
        if not saves.is_dir():
            raise RuntimeError('no save directory %s' % saves)
        region = Region(saves / 'region')
        tree = find_tree(region, spawn)
        ore = find_ore(region, spawn)
        if tree is None:
            raise RuntimeError('no tree with four reachable logs within 6 chunks of the spawn')
        if ore is None:
            raise RuntimeError('no smeltable HBM ore in solid rock within 6 chunks of the spawn')
        log0, v, log_id = tree
        o, ft, hd, ore_id = ore
        state['tree'], state['ore'] = (log0, v, log_id), (o, ft, hd, ore_id)
        for c in ('gamerule doMobSpawning false', 'gamerule doDaylightCycle false', 'time set 1000', 'weather clear'):
            ctx.server(c, allow_error=True)
        if sum(inventory(ctx).values()):
            raise RuntimeError('the inventory is not empty at the start: %s' % dict(inventory(ctx)))
        planks = log_id.replace('_log', '_planks')
        p = add(log0, v)
        q = add(p, v)
        face = FACE[v]                      # the log's face towards the standing cell
        # three logs by hand, from the cell beside the foot of the tree
        got = Counter()
        for k in range(3):
            d, gone = mine(ctx, (log0[0], log0[1] + k, log0[2]), face, LOG_HOLD, p)
            got.update(d)
        inv = inventory(ctx)
        ctx.check(W + 'opening-wood', inv[log_id] == 3,
                  '%s at %s, stood at %s: picked up %s; inventory %s' % (log_id, list(log0), list(p), dict(got), dict(inv)))
        # planks, a crafting table and sticks in the inventory grid
        ctx.step('key', key='key.keyboard.e', after=4)
        ctx.step('screen', expect='InventoryScreen')
        put_all(ctx, INV_MENU, log_id, 1)
        shift_click(ctx, 0)
        put(ctx, INV_MENU, planks, [1, 2, 3, 4])
        shift_click(ctx, 0)
        put(ctx, INV_MENU, planks, [1, 3])
        shift_click(ctx, 0)
        ctx.step('close')
        back = FACE[tuple(-c for c in v)]
        place(ctx, 'minecraft:crafting_table', q, p)
        open_block(ctx, q, back, p, 'CraftingScreen')
        put(ctx, CRAFT_MENU, planks, [1, 2, 3])
        put(ctx, CRAFT_MENU, 'minecraft:stick', [5, 8])
        shift_click(ctx, 0)
        ctx.step('close')
        # the table goes along: broken at hand speed (hardness 2.5: 1 / 2.5 / 30 a tick = 75 ticks; the new pickaxe sits in the
        # selected slot and is not the table's tool) and picked up
        d_table, table_gone = mine(ctx, q, back, TABLE_HOLD, p)
        inv = inventory(ctx)
        want = {planks: 3, 'minecraft:stick': 2, 'minecraft:crafting_table': 1, 'minecraft:wooden_pickaxe': 1}
        ctx.check(W + 'opening-tools', dict(inv) == want and table_gone and d_table == {'minecraft:crafting_table': 1},
                  'inventory %s (want %s); the table at %s broken: gone %s, picked up %s' % (dict(inv), want, list(q), table_gone, d_table))
        # the pocket under the ore: two cells cleared (预写: the player's standing room), then real mining
        ctx.server('fill %d %d %d %d %d %d minecraft:air' % (ft + hd))
        hold(ctx, 'minecraft:wooden_pickaxe')
        d, gone = mine(ctx, o, 'south', ORE_HOLD, ft)
        ctx.check(W + 'opening-ore', gone and d == {ore_id: 1},
                  '%s at %s (pocket feet %s, the two pocket cells 预写 as air): gone %s, picked up %s' % (ore_id, list(o), list(ft), gone, d))
        cobble = Counter()
        for pos, f in pocket_targets(o, ft, hd):
            d, gone = mine(ctx, pos, f, STONE_HOLD[region.at(*pos)], ft)
            cobble.update(d)
        inv = inventory(ctx)
        n_cobble = sum(inv[c] for c in COBBLE)
        if n_cobble < 8:
            raise RuntimeError('cobblestone picked up: %s' % dict(cobble))
        w1 = add(ft, (-1, 0, 0))
        e1 = add(ft, (1, 0, 0))
        place(ctx, 'minecraft:crafting_table', w1, ft)
        open_block(ctx, w1, 'east', ft, 'CraftingScreen')
        ring = [1, 2, 3, 4, 6, 7, 8, 9]
        for c in COBBLE:
            if not ring:
                break
            k = min(inv[c], len(ring))
            if k:
                put(ctx, CRAFT_MENU, c, ring[:k])
                ring = ring[k:]
        shift_click(ctx, 0)
        ctx.step('close')
        place(ctx, 'minecraft:furnace', e1, ft)
        ctx.check(W + 'opening-furnace', n_cobble == 8 and is_block(ctx, w1, 'minecraft:crafting_table') and is_block(ctx, e1, 'minecraft:furnace'),
                  'mined %s; cobble in inventory %d; table at %s, furnace at %s' % (dict(cobble), n_cobble, list(w1), list(e1)))
        # smelting
        ingot = H + SMELTABLE[ore_id.split(':')[1]][0]
        open_block(ctx, e1, 'west', ft, 'FurnaceScreen')
        put(ctx, FURNACE_MENU, ore_id, [0])
        put(ctx, FURNACE_MENU, planks, [1], each=2)
        ctx.step('close')
        t0 = ctx.server()['game_time']
        ctx.step('wait', ticks=COOK + 30)
        items = furnace_items(ctx, e1)
        t1 = ctx.server()['game_time']
        before = inventory(ctx)
        open_block(ctx, e1, 'west', ft, 'FurnaceScreen')
        shift_click(ctx, 2)
        ctx.step('close')
        d = delta(inventory(ctx), before)
        ctx.check(W + 'opening-smelt', t1 - t0 >= COOK and items.get(2) == (ingot, 1) and items.get(1) == (planks, 1) and items.get(0) is None
                  and d == {ingot: 1},
                  '%d ticks: furnace slots %s (want result %s x1, 1 plank left, input empty); taken out: %s' % (t1 - t0, items, ingot, d))
        state['furnace'] = e1
        state['opening'] = True
    section(ctx, open_rows, opening, 'survival opening')

    # leave and reopen: the same server readings again
    def reopen():
        if not state.get('opening'):
            raise RuntimeError('the opening did not complete; its state is the comparison')
        inv0 = inventory_raw(ctx)
        f0 = furnace_items(ctx, state['furnace'])
        ctx.step('leave')
        ctx.step('openworld', world=world.get('name'))
        ctx.step('wait', ticks=20)
        inv1 = inventory_raw(ctx)
        f1 = furnace_items(ctx, state['furnace'])
        ctx.check(W + 'reopen', inv0 == inv1 and f0 == f1 and len(inv0) > 0,
                  'inventory before %s; after %s; furnace before %s, after %s' % (inv0, 'same' if inv1 == inv0 else inv1, f0, 'same' if f1 == f0 else f1))
    section(ctx, [W + 'reopen'], reopen, 'reopen')

    def reopen_worldgen():
        scans = state.get('scans', {})
        if 'overworld' not in scans:
            raise RuntimeError('no scan')
        ow = scans['overworld']
        probes = []
        for name in ('crashed_bomb', 'mine_ap', 'ore_oil', 'ore_bedrock_oil'):
            b = ow['blocks'].get(H + name)
            if b:
                probes.append((H + name, b['samples'][0]))
        for pos in (ow.get('blueprint_chests') or {}).get('positions', [])[:1]:
            probes.append(('minecraft:chest', pos))
        if not probes:
            raise RuntimeError('none of the rare blocks was scanned')
        rows = []
        ok = True
        waiting = None
        for block, pos in probes:
            cx, cz = pos[0] >> 4, pos[2] >> 4
            ctx.server('forceload add %d %d' % (cx * 16, cz * 16), allow_error=True)
            ctx.step('wait', ticks=10)
            there = is_block(ctx, pos, block)
            if block == H + 'mine_ap':
                waiting = _lib.block_data(ctx, pos).get('Waiting')
                there = there and waiting in (1, True)
            ctx.server('forceload remove %d %d' % (cx * 16, cz * 16), allow_error=True)
            ok = ok and there
            rows.append('%s at %s: %s' % (block, pos, 'there' if there else 'MISSING'))
        ctx.check(W + 'reopen-worldgen', ok and (waiting in (1, True) or not ow['blocks'].get(H + 'mine_ap')),
                  '; '.join(rows) + '; landmine Waiting %s' % waiting)
    section(ctx, [W + 'reopen-worldgen'], reopen_worldgen, 'reopen worldgen')

    def oil_look():
        scans = state.get('scans', {})
        if 'overworld' not in scans:
            raise RuntimeError('no scan')
        spills = scans['overworld']['blocks'].get(H + 'oil_spill')
        if not spills:
            raise RuntimeError('no oil spill in the %d scanned chunks' % scans['overworld']['scanned'])
        region = Region(saves / 'region')
        best, tried = None, 0
        for cx, cz, _ in spills.get('chunks', []):
            for x, y, z in region.find(cx, cz, lambda n: n == H + 'oil_spill'):
                tried += 1
                oily = sum(1 for dx in range(-7, 8) for dz in range(-7, 8) for dy in range(-3, 2) if region.at(x + dx, y + dy, z + dz) in OILY_SAND)
                tar = sum(1 for dx in range(-4, 5) for dz in range(-4, 5) for dy in range(-8, 1) if region.at(x + dx, y + dy, z + dz) == H + 'ore_oil_sand')
                if oily >= 3 and tar >= 1 and (best is None or oily + tar > best[0]):
                    best = (oily + tar, (x, y, z), oily, tar)
        if best is None:
            ctx.not_run('oil-extraction.sand-oil-bubble-look',
                        '%d oil spills in the scan, none with oily sand around it and tar sand just below: no sand oil bubble to look at' % tried)
            return
        x, y, z = best[1]
        state['oil_look'] = best
        ctx.server('gamemode spectator @a')
        try:
            ctx.step('view', eye=[x + 0.5, y + 12.0, z + 8.5], look_at=[x + 0.5, y + 0.5, z + 0.5], fly=True, hide_gui=True)
            wait_loaded(ctx, x, z, 3)
            ctx.step('wait', ticks=60)
            shots = [ctx.step('shot', file=ctx.shot_name('sand-oil-bubble-patch'))['image']['file']]
            # the shaft is one block wide and two deep over the spill (MapGenBubble.java:148-174): only a view from nearly straight above reaches its floor
            for label, eye in (('shaft', [x + 0.5, y + 5.0, z + 1.1]), ('shaft-close', [x + 0.5, y + 3.2, z + 0.9])):
                ctx.step('view', eye=eye, look_at=[x + 0.5, y + 0.5, z + 0.5], fly=True, hide_gui=True)
                ctx.step('wait', ticks=20)
                shots.append(ctx.step('shot', file=ctx.shot_name('sand-oil-bubble-' + label))['image']['file'])
        finally:
            ctx.step('view', pos=[spawn[0], spawn[1], spawn[2]], pitch=0.0, yaw=0.0, fly=False, hide_gui=False, allow_fail=True)
            ctx.server('gamemode survival @a', allow_error=True)
        ctx.review('oil-extraction.sand-oil-bubble-look',
                   'oil spill at %s with %d oily sand blocks within 7 blocks and %d tar sand blocks within 4 blocks below (seed %s); first picture from 12 blocks up '
                   'and 8 south: the patch of oily sand (darker, brown-black) around the spill; second and third pictures from 5 and 3 blocks up, nearly '
                   'straight above the shaft: cracked stone blocks around a shaft two blocks deep with the dark oil spill layer on its floor' % (list(best[1]), best[2], best[3], state.get('seed')), shots)
    section(ctx, ['oil-extraction.sand-oil-bubble-look'], oil_look, 'oil bubble look')


def judge_scan(ctx, state):
    """Verdicts for the scan rows from the two scan reports."""
    W = 'world-generation.'
    ow, ne = state['scans']['overworld'], state['scans']['nether']
    n_ow, n_ne = ow['scanned'], ne['scanned']
    cand = [c for c in ow.get('scanned_chunks', []) if is_blueprint_chunk(c[0], c[1])]
    walk_text = '; '.join('%s %d,%d %ss%s' % (w['dim'].split(':')[1], w['x'], w['z'], w['s'], '' if w['loaded'] else ' (not all loaded)')
                          for w in state['walk'])
    ctx.check(W + 'scan-range', n_ow >= N_MIN_OVERWORLD and n_ne >= N_MIN_NETHER and len(cand) >= 8,
              'full chunks scanned: overworld %d (scan %ss), nether %d (scan %ss); blueprint candidate chunks %d %s; seed %s; '
              'coltan centre %s; badlands point %s; walk: %s%s'
              % (n_ow, ow.get('wall_s'), n_ne, ne.get('wall_s'), len(cand), cand, state.get('seed'), state.get('coltan_centre'),
                 state.get('badlands'), walk_text, '; walk stopped: ' + state['walk_reason'] if state.get('walk_reason') else ''))
    for name, e in blocks().items():
        eid = eid_of(name)
        rule = rule_of(name, e)
        dims = sorted(e['dims'])
        counts = {d: (ow if d == 'overworld' else ne if d == 'nether' else dict(blocks={}))['blocks'].get(H + name) for d in dims}
        n = sum(c['count'] for c in counts.values() if c)
        where = '; '.join('%s: %s' % (d, 'n=%d in %d chunks, y %d..%d, e.g. %s' % (c['count'], c['chunks_with'], c['miny'], c['maxy'], c['samples'][0])
                                      if c else 'none') for d, c in counts.items())
        n_scan = sum(n_ow if d == 'overworld' else n_ne if d == 'nether' else 0 for d in dims)
        if rule == 'end':
            ctx.not_run(eid, 'End-only block (%s): the smoke scans the overworld and the nether only' % ', '.join(e['features']))
        elif rule == 'absent':
            other = ne['blocks'].get(H + name) or ow['blocks'].get(H + name)
            ctx.check(eid, n == 0 and not other, '%s; %d chunks scanned' % (where, n_scan))
        elif rule == 'list':
            ctx.check(eid, n > 0, '%s; %d chunks scanned. List problem: %s' % (where, n_scan, LIST_PROBLEMS[name]))
        elif rule == 'common':
            ctx.check(eid, n > 0, '%s; %d chunks scanned' % (where, n_scan))
        elif n > 0:
            ctx.check(eid, True, '%s; %d chunks scanned' % (where, n_scan))
        elif rule == 'rare':
            p_none = 1.0
            for f in e['features']:
                p_none *= (1 - RARE[f][0]) ** n_scan
            note = ''
            if name == 'sand_oily_red':
                note = '; it needs red sand under an oil spot (badlands): badlands point %s' % (state.get('badlands'),)
            elif name in ('sand_oily', 'plant_mustard_willow', 'dirt_oily', 'dirt_dead', 'stone_cracked', 'oil_spill'):
                note = '; P(none) is that of no source event at all: an event places this block only on suitable ground'
            ctx.review(eid, 'none in %d %s chunks; P(no source event in N chunks) = %.2g%s' % (n_scan, '/'.join(dims), p_none, note))
        else:
            ctx.review(eid, 'none in %d %s chunks: the noise-placed region (%s) is outside the scanned area' % (n_scan, '/'.join(dims), ', '.join(e['features'])))
    bp = ow.get('blueprint_chests') or dict(count=0, positions=[])
    if bp['count'] > 0:
        ctx.check('blueprints.worldgen-chest', True, '%d blueprint chests at %s; %d candidate chunks scanned' % (bp['count'], bp['positions'], len(cand)))
    else:
        ctx.review('blueprints.worldgen-chest', 'none in %d candidate chunks %s; P(none) = 0.5^%d = %.2g' % (len(cand), cand, len(cand), 0.5 ** len(cand)))
    oil = ow['blocks'].get(H + 'ore_bedrock_oil')
    groups = deposits(oil.get('chunks', [])) if oil else 0
    lo, hi = poisson_range(n_ow / 200.0)
    lo64, hi64 = poisson_range(n_ow / 64.0)
    ctx.check(W + 'bedrock-oil-rate', lo <= groups <= hi,
              '%d deposits in %d chunks; original 1/200: mean %.1f, 99.9 %% range %d..%d; a 1/64 rate would give mean %.1f, range %d..%d'
              % (groups, n_ow, n_ow / 200.0, lo, hi, n_ow / 64.0, lo64, hi64))
